      @media (max-width: 560px) {
        .app-shell {
          width: min(100% - 1rem, 1120px);
          padding-top: 0.6rem;
        }

        .panel,
        .image-frame,
        .dialog-card {
          border-radius: 22px;
        }

        .actions,
        .dialog-actions {
          flex-direction: column;
        }

        .button {
          width: 100%;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
          transition-duration: 0.01ms !important;
          scroll-behavior: auto !important;
        }
      }

      @media (forced-colors: active) {
        :root {
          --surface: Canvas;
          --surface-strong: Canvas;
          --surface-border: CanvasText;
          --text: CanvasText;
          --muted: CanvasText;
          --subtle: CanvasText;
          --primary: Highlight;
          --primary-strong: Highlight;
          --danger: Mark;
          --danger-strong: Mark;
          --danger-soft: Canvas;
        }

        .panel,
        .image-frame,
        .empty-card,
        .dialog-card,
        .meta-chip,
        .detail-card,
        .button,
        .floating-badge {
          border: 1px solid CanvasText;
          box-shadow: none;
        }

        .button-primary,
        .button-danger,
        .button-secondary,
        nav a[aria-current="page"],
        .brand-mark,
        .eyebrow,
        .dialog-tag {
          forced-color-adjust: none;
          background: ButtonFace;
          color: ButtonText;
        }

        dialog::backdrop {
          background: rgba(0, 0, 0, 0.7);
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>

    <div class="app-shell" id="app-shell">
      <header>
        <div class="brand" aria-label="Northstar Library">
          <span class="brand-mark" aria-hidden="true">N</span>
          <span>Northstar Library</span>
        </div>

        <nav aria-label="Primary">
          <ul>
            <li><a href="/preview" aria-current="page">Preview</a></li>
            <li><a href="/collections">Collections</a></li>
            <li><a href="/shared">Shared</a></li>
          </ul>
        </nav>
      </header>

      <main id="maincontent" tabindex="-1">
        <section class="hero" aria-labelledby="page-title">
          <span class="eyebrow">Image preview</span>
          <h1 id="page-title">Keep only the images you still need.</h1>
          <p class="hero-copy">
            Review image details, confirm destructive changes, and keep your library tidy without
            losing context.
          </p>
        </section>

        <section class="preview-layout" aria-label="Selected image preview">
          <article class="image-frame" id="preview-card" aria-labelledby="image-title">
            <figure>
              <div class="image-stage">
                <img
                  src="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1200&q=80"
                  alt="Preview of ocean cliffs at sunset with mist over the water"
                />
                <span class="floating-badge">Sunset Study • Final edit</span>
              </div>
            </figure>
          </article>

          <aside class="panel stack" aria-labelledby="image-title">
            <div class="stack">
              <div class="meta-row" aria-label="Image metadata">
                <span class="meta-chip">Photography</span>
                <span class="meta-chip">5472 × 3648 px</span>
                <span class="meta-chip">14.2 MB</span>
              </div>

              <div class="stack">
                <h2 id="image-title">Sunset over the north cliffs</h2>
                <p class="supporting-copy">
                  Captured for the Spring campaign. Deleting this image removes it from your
                  personal library and any unsaved selections.
                </p>
              </div>
            </div>

            <dl class="stack" aria-label="Image details">
              <div class="detail-card">
                <dt>Uploaded by</dt>
                <dd>Maya Patel</dd>
              </div>
              <div class="detail-card">
                <dt>Created</dt>
                <dd>May 4, 2026</dd>
              </div>
              <div class="detail-card">
                <dt>Library folder</dt>
                <dd>Campaign / Spring launch</dd>
              </div>
            </dl>

            <div class="actions" id="action-bar">
              <button class="button button-danger trigger" id="open-dialog" type="button">
                Delete image
              </button>
            </div>

            <p class="status-region" id="status-message" role="status" aria-live="polite"></p>
          </aside>
        </section>

        <section class="empty-state" id="empty-state" hidden aria-labelledby="empty-title">
          <div class="empty-card">
            <div class="empty-icon" aria-hidden="true">✓</div>
            <h2 class="focus-anchor" id="empty-title" tabindex="-1">Image deleted from your library</h2>
            <p class="supporting-copy">
              The preview has been removed. You can return to your collections to choose another
              image.
            </p>
          </div>
        </section>
      </main>
    </div>

    <dialog id="delete-dialog" aria-labelledby="delete-dialog-title" aria-describedby="delete-dialog-body">
      <div class="dialog-card">
        <div class="dialog-header">
          <span class="dialog-tag">Confirm deletion</span>
          <h2 id="delete-dialog-title">Delete this image from your library?</h2>
          <p class="dialog-body" id="delete-dialog-body">
            This removes <strong>Sunset over the north cliffs</strong> from your library. This
            action can’t be undone.
          </p>
        </div>

        <div class="dialog-actions">
          <button class="button button-secondary" id="cancel-delete" type="button" autofocus>
            Cancel
          </button>
          <button class="button button-danger" id="confirm-delete" type="button">Delete image</button>
        </div>
      </div>
    </dialog>

    <script>
      const appShell = document.getElementById("app-shell");
      const previewCard = document.getElementById("preview-card");
      const actionBar = document.getElementById("action-bar");
      const emptyState = document.getElementById("empty-state");
      const emptyTitle = document.getElementById("empty-title");
      const statusMessage = document.getElementById("status-message");
      const deleteDialog = document.getElementById("delete-dialog");
      const openDialogButton = document.getElementById("open-dialog");
      const cancelDeleteButton = document.getElementById("cancel-delete");
      const confirmDeleteButton = document.getElementById("confirm-delete");
      const supportsModalDialog = typeof deleteDialog.showModal === "function";
      let lastTrigger = null;

      function openDialog(trigger) {
        lastTrigger = trigger;

        if (supportsModalDialog) {
          deleteDialog.showModal();
          return;
        }

        appShell.inert = true;
        deleteDialog.setAttribute("open", "");
        deleteDialog.setAttribute("role", "alertdialog");
        deleteDialog.setAttribute("aria-modal", "true");
        cancelDeleteButton.focus();
      }

      function closeDialog(returnValue) {
        if (supportsModalDialog) {
          deleteDialog.close(returnValue);
          return;
        }

        deleteDialog.dataset.returnValue = returnValue;
        deleteDialog.removeAttribute("open");
        appShell.inert = false;

        if (returnValue === "delete") {
          applyDeleteState();
          return;
        }

        if (lastTrigger && document.contains(lastTrigger)) {
          lastTrigger.focus();
        }
      }

      function applyDeleteState() {
        previewCard.hidden = true;
        actionBar.hidden = true;
        emptyState.hidden = false;
        statusMessage.textContent = "Image deleted from your library.";
        emptyTitle.focus();
      }

      openDialogButton.addEventListener("click", (event) => {
        openDialog(event.currentTarget);
      });

      cancelDeleteButton.addEventListener("click", () => {
        closeDialog("cancel");
      });

      confirmDeleteButton.addEventListener("click", () => {
        closeDialog("delete");
      });

      deleteDialog.addEventListener("close", () => {
        if (deleteDialog.returnValue === "delete") {
          applyDeleteState();
          return;
        }

        if (lastTrigger && document.contains(lastTrigger)) {
          lastTrigger.focus();
        }
      });

      if (!supportsModalDialog) {
        deleteDialog.addEventListener("keydown", (event) => {
          if (event.key === "Escape") {
            event.preventDefault();
            closeDialog("cancel");
          }
        });
      }
    </script>
  </body>
</html>
